-- TIMESTAMP 리터럴 기본값은 세션 time_zone 을 UTC 로 정한 뒤에만 받는다 (리뷰 4회차 M-1): MySQL 은 쓰는 세션의 시간대에서 UTC 로 바꿔 저장하고,
-- td-export 는 UTC 세션에서 읽는다. UTC 로 정한 세션의 값은 쓴 그대로 찍힌다
SET time_zone = '+00:00';
ALTER TABLE member
  ADD COLUMN d1 DATE DEFAULT '2020-01-01',
  ADD COLUMN dt1 DATETIME NOT NULL DEFAULT '2020-01-01',
  ADD COLUMN dt2 DATETIME(3) DEFAULT '2020-01-01 10:20:30',
  ADD COLUMN dt3 DATETIME(6) DEFAULT '2020-01-01 10:20:30.12',
  ADD COLUMN dt4 DATETIME DEFAULT '2020-01-01 10:20',
  ADD COLUMN ts1 TIMESTAMP NULL DEFAULT '2030-01-01',
  ADD COLUMN ts2 TIMESTAMP(3) NULL DEFAULT '2030-01-01 01:02:03',
  ADD COLUMN t1 TIME DEFAULT '12:34',
  ADD COLUMN t2 TIME(2) DEFAULT '1:02:03',
  ADD COLUMN t3 TIME DEFAULT '-838:59:59',
  ADD COLUMN t4 TIME(3) DEFAULT '-00:00:00.123',
  ADD COLUMN t5 TIME(3) DEFAULT '-00:00:00.000';
ALTER TABLE member ALTER COLUMN dt1 SET DEFAULT '2021-12-31 23:59';
CREATE TABLE ev (id INT PRIMARY KEY, at DATETIME NOT NULL DEFAULT '1970-01-02', due DATE NOT NULL DEFAULT '2000-02-29', ts TIMESTAMP(6) NULL DEFAULT '2020-06-01 00:00:00');
